CREATE TABLE public.retro_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, invite_code uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invite_code));
GRANT SELECT, DELETE ON public.retro_sessions TO authenticated;
GRANT ALL ON public.retro_sessions TO service_role;
ALTER TABLE public.retro_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.retro_members (session_id uuid NOT NULL REFERENCES public.retro_sessions(id) ON DELETE CASCADE, user_id uuid NOT NULL, display_name text NOT NULL DEFAULT 'Partner', answers jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,user_id), CONSTRAINT member_name_length CHECK(char_length(display_name) BETWEEN 1 AND 80), CONSTRAINT answers_object CHECK(jsonb_typeof(answers) = 'object'));
GRANT SELECT, UPDATE, DELETE ON public.retro_members TO authenticated;
GRANT ALL ON public.retro_members TO service_role;
ALTER TABLE public.retro_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_retro_member(sid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.retro_members WHERE session_id=sid AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_retro_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_retro_member(uuid) TO authenticated;
CREATE POLICY session_read ON public.retro_sessions FOR SELECT TO authenticated USING(public.is_retro_member(id));
CREATE POLICY session_delete ON public.retro_sessions FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE POLICY member_read ON public.retro_members FOR SELECT TO authenticated USING(public.is_retro_member(session_id));
CREATE POLICY member_update ON public.retro_members FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY member_leave ON public.retro_members FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.create_retro_session(member_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL OR char_length(trim(member_name)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'Bitte anmelden und Namen eingeben'; END IF; INSERT INTO public.retro_sessions(owner_id) VALUES(auth.uid()) RETURNING id INTO sid; INSERT INTO public.retro_members(session_id,user_id,display_name) VALUES(sid,auth.uid(),trim(member_name)); RETURN sid; END $$;
CREATE FUNCTION public.join_retro_session(code uuid, member_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL OR char_length(trim(member_name)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'Bitte anmelden und Namen eingeben'; END IF; SELECT id INTO sid FROM public.retro_sessions WHERE invite_code=code FOR UPDATE; IF sid IS NULL THEN RAISE EXCEPTION 'Einladung nicht gefunden'; END IF; IF NOT public.is_retro_member(sid) AND (SELECT count(*) FROM public.retro_members WHERE session_id=sid)>=2 THEN RAISE EXCEPTION 'Diese Retro ist bereits zu zweit'; END IF; INSERT INTO public.retro_members(session_id,user_id,display_name) VALUES(sid,auth.uid(),trim(member_name)) ON CONFLICT DO NOTHING; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.create_retro_session(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_retro_session(text) TO authenticated;
REVOKE ALL ON FUNCTION public.join_retro_session(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_retro_session(uuid,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.retro_members;